$_ADMINLANG['domains']['slabsintro'] = "ສາມາດສ້າງຊັ້ນລາຄາ (Pricing Slabs) ເພື່ອນຳສະເໜີລາຄາທີ່ແຕກຕ່າງກັນໃຫ້ກັບກຸ່ມລູກຄ້າ. ຊັ້ນລາຄາຈະຜູກກັບກຸ່ມລູກຄ້າ, ດັ່ງນັ້ນທ່ານຕ້ອງຕັ້ງລາຄາສຳລັບຊັ້ນພື້ນຖານເລີ່ມຕົ້ນກ່ອນ, ແລະ ຫຼັງຈາກນັ້ນຈຶ່ງຕັ້ງລາຄາກຳນົດເອງສຳລັບກຸ່ມລູກຄ້າທີ່ຕ້ອງການ.";
