$_ADMINLANG['domains']['contactsChanged'] = "ຄຳຮ້ອງຂໍປ່ຽນແປງຂໍ້ມູນ WHOIS ໄດ້ເລີ່ມຂະບວນການຢືນຢັນຜູ້ຕິດຕໍ່. ອີເມລໄດ້ຖືກສົ່ງໄປຫາເຈົ້າຂອງໂດເມນທີ່ຈົດທະບຽນເພື່ອອະນຸມັດການປ່ຽນແປງ.";
$_ADMINLANG['domains']['contactsChangedDate'] = "ຄຳຮ້ອງຂໍປ່ຽນແປງຂໍ້ມູນ WHOIS ໄດ້ເລີ່ມຂະບວນການຢືນຢັນຜູ້ຕິດຕໍ່. ອີເມລໄດ້ຖືກສົ່ງໄປຫາເຈົ້າຂອງໂດເມນທີ່ຈົດທະບຽນເພື່ອອະນຸມັດການປ່ຽນແປງ. ການດຳເນີນການນີ້ຕ້ອງສຳເລັດພາຍໃນວັນທີ :date.";
$_ADMINLANG['domains']['newRegistration'] = "ອີເມລໄດ້ຖືກສົ່ງໄປຫາເຈົ້າຂອງໂດເມນທີ່ຈົດທະບຽນແລ້ວ. ຕ້ອງດຳເນີນການຢືນຢັນໃຫ້ສຳເລັດເພື່ອຫຼີກເວັ້ນການລະງັບການໃຊ້ງານ.";
$_ADMINLANG['domains']['newRegistrationDate'] = "ອີເມລໄດ້ຖືກສົ່ງໄປຫາເຈົ້າຂອງໂດເມນທີ່ຈົດທະບຽນແລ້ວ. ຕ້ອງດຳເນີນການຢືນຢັນໃຫ້ສຳເລັດພາຍໃນວັນທີ :date ເພື່ອຫຼີກເວັ້ນການລະງັບການໃຊ້ງານ.";
