$_ADMINLANG['domains']['irtpLockDescription'] = "ໂດເມນນີ້ຖືກລັອກການຍ້າຍໄວ້ໃນປັດຈຸບັນ ເນື່ອງຈາກການປ່ຽນແປງຜູ້ຕິດຕໍ່ ຫຼື ການຈົດທະບຽນໃໝ່.";
$_ADMINLANG['domains']['irtpLockDescriptionDate'] = "ໂດເມນນີ້ຖືກລັອກການຍ້າຍໄວ້ໃນປັດຈຸບັນ ເນື່ອງຈາກການປ່ຽນແປງຜູ້ຕິດຕໍ່ ຫຼື ການຈົດທະບຽນໃໝ່. ການລັອກນີ້ຈະໝົດອາຍຸໃນວັນທີ :date.";
