$_ADMINLANG['domains']['changePending'] = "ການປ່ຽນແປງທີ່ຮ້ອງຂໍໄດ້ເລີ່ມຂະບວນການຢືນຢັນຜູ້ຕິດຕໍ່. ອີເມລຢືນຢັນຄວາມເປັນເຈົ້າຂອງໄດ້ຖືກສົ່ງໄປຫາ :email ແລ້ວ. ຄລິກທີ່ລິ້ງໃນອີເມລເພື່ອໃຫ້ມີຜົນບັງຄັບໃຊ້.";
$_ADMINLANG['domains']['changePendingDate'] = "ການປ່ຽນແປງທີ່ຮ້ອງຂໍໄດ້ເລີ່ມຂະບວນການຢືນຢັນຜູ້ຕິດຕໍ່. ອີເມລຢືນຢັນຄວາມເປັນເຈົ້າຂອງໄດ້ຖືກສົ່ງໄປຫາ :email ແລ້ວ. ຄລິກທີ່ລິ້ງໃນອີເມລພາຍໃນ :days ວັນ ເພື່ອໃຫ້ມີຜົນບັງຄັບໃຊ້.";
