$_ADMINLANG['orders']['confirmCancelDelete'] = "ທ່ານແນ່ໃຈຫຼືບໍ່ວ່າຕ້ອງການຍົກເລີກ ແລະ ລຶບລາຍການສັ່ງຊື້ນີ້? ນີ້ຈະລັນການຍົກເລີກໂມດູນສຳລັບທຸກ ຜະລິດຕະພັນ/ບໍລິການ ທີ່ກຳລັງໃຊ້ງານ ແລະ ລຶບທຸກ ຜະລິດຕະພັນ/ບໍລິການ ແລະ ໃບບິນທີ່ກ່ຽວຂ້ອງ.";
