$_ADMINLANG['transactions']['amountOutCannotBeUsedWithAddCredit'] = "ທ່ານບໍ່ສາມາດໃຊ້ ການເພີ່ມເປັນເຄຣດິດ ແລະ ຈຳນວນເງິນອອກ ພ້ອມກັນໄດ້. ກະລຸນາໃຊ້ການຈັດການເຄຣດິດຈາກໜ້າສະຫຼຸບລູກຄ້າ.";
$_ADMINLANG['transactions']['invoiceIDAndCreditInvalid'] = "ທ່ານບໍ່ສາມາດໃຊ້ ການເພີ່ມເປັນເຄຣດິດ ແລະ ລະບຸໄອດີໃບແຈ້ງໜີ້ ພ້ອມກັນໄດ້. ການຊຳລະເກີນໃນໃບແຈ້ງໜີ້ຈະຖືກປ່ຽນເປັນເຄຣດິດໂດຍອັດຕະໂນມັດ.";
