$_ADMINLANG['products']['title'] = "ຜະລິດຕະພັນ/ບໍລິການ";
$_ADMINLANG['products']['description'] = "ບ່ອນນີ້ແມ່ນບ່ອນທີ່ທ່ານຕັ້ງຄ່າຜະລິດຕະພັນ ແລະ ບໍລິການທັງໝົດຂອງທ່ານ. ແຕ່ລະຜະລິດຕະພັນຕ້ອງຖືກກຳນົດໃຫ້ຢູ່ໃນກຸ່ມ ເຊິ່ງສາມາດເລືອກໃຫ້ສະແດງ ຫຼື ຊ່ອນຈາກໜ້າການສັ່ງຊື້ໄດ້. ຜະລິດຕະພັນທີ່ຢູ່ໃນກຸ່ມທີ່ຊ່ອນຢູ່ຍັງສາມາດສັ່ງຊື້ໄດ້ໂດຍໃຊ້ລິ້ງການສັ່ງຊື້ໂດຍກົງ.";
