$_ADMINLANG['backups']['description'] = "ພວກເຮົາແນະນຳໃຫ້ສຳຮອງຂໍ້ມູນເປັນປະຈຳເພື່ອປ້ອງກັນຂໍ້ມູນສູນຫາຍ. WHMCS ສາມາດສຳຮອງຂໍ້ມູນຖານຂໍ້ມູນອັດຕະໂນມັດລາຍວັນຜ່ານຫຼາຍຮູບແບບ. ເພື່ອຄວາມປອດໄພ, ທ່ານຄວນເຮັດການສຳຮອງຂໍ້ມູນດ້ວຍຕົນເອງນຳອີກ.";
