$_ADMINLANG['supportticketdepts']['changessavesuccessdesc'] = "ການປ່ຽນແປງຂອງທ່ານຕໍ່ກັບພະແນກຊ່ວຍເຫຼືອໄດ້ຖືກບັນທຶກແລ້ວ.";
$_ADMINLANG['supportticketdepts']['supportticketdeptsconfigheredesc'] = "ນີ້ແມ່ນບ່ອນທີ່ທ່ານຕັ້ງຄ່າພະແນກປີ້ຊ່ວຍເຫຼືອຂອງທ່ານ. ທີ່ຢູ່ອີເມລທີ່ທ່ານປ້ອນຈະເປັນທີ່ຢູ່ທີ່ໃຊ້ເພື່ອລໍຖ້າຮັບອີເມລທີ່ສົ່ງມາຫາພະແນກນີ້ ແລະ ອີເມລທັງໝົດສຳລັບພະແນກກໍຈະຖືກສົ່ງໂດຍໃຊ້ທີ່ຢູ່ນີ້ຄືກັນ. ການສົ່ງຕໍ່ອີເມລ (Email piping) ຊ່ວຍໃຫ້ສາມາດເປີດປີ້ ແລະ ຕອບກັບຜ່ານອີເມລໄດ້ ແລະ ສາມາດຕັ້ງຄ່າໄດ້ໂດຍໃຊ້ວິທີໃດໜຶ່ງລຸ່ມນີ້.";
