# Resolver Check
$_ADMINLANG['utilitiesresolvercheck']['domainresolverchecktitle'] = "ເຄື່ອງມືກວດສອບການຊີ້ໂດເມນ (Domain Resolver Checker)";
$_ADMINLANG['utilitiesresolvercheck']['pagedesc'] = "ເຄື່ອງມືນີ້ຊ່ວຍໃຫ້ທ່ານສາມາດກວດສອບທີ່ຢູ່ IP ທີ່ແຕ່ລະໂດເມນໃນລະບົບ WHMCS ຂອງທ່ານກຳລັງຊີ້ໄປຫາ. ນີ້ຊ່ວຍໃຫ້ທ່ານເຫັນໄດ້ງ່າຍວ່າໂດເມນໃດທີ່ບໍ່ໄດ້ຊີ້ມາທີ່ເຊີບເວີຂອງທ່ານອີກຕໍ່ໄປ ແລະ ຊ່ວຍລະບຸລູກຄ້າທີ່ອາດຈະບໍ່ໄດ້ໃຊ້ບໍລິການຂອງທ່ານແລ້ວ ເພື່ອຄືນຊັບພະຍາກອນລະບົບ.";
