$_ADMINLANG['utilitiesresolvercheck']['terminateonserver'] = "ຍົກເລີກການບໍລິການໃນເຊີບເວີ";
$_ADMINLANG['utilitiesresolvercheck']['delsureterminateonserver'] = "ທ່ານແນ່ໃຈວ່າຕ້ອງການເຮັດສິ່ງນີ້? ນີ້ຈະສົ່ງຄຳສັ່ງຍົກເລີກຂອງໂມດູນໄປຫາເຊີບເວີປາຍທາງ (ລຶບໄຟລ໌ທັງໝົດ), ລວມທັງປ່ຽນສະຖານະໃນ WHMCS ເປັນ Terminated ເພື່ອຢຸດການຮຽກເກັບເງິນໃນອະນາຄົດ.";
