$_ADMINLANG['promos']['upgradesinstructions'] = "ຄຳແນະນຳໂປຣໂມຊັນອັບເກຣດ";
$_ADMINLANG['promos']['upgradesinstructionsinfo'] = "ສຳລັບລະຫັດໂປຣໂມຊັນອັບເກຣດທັງໝົດ, ຊ່ອງຂໍ້ມູນ 'ໃຊ້ໄດ້ກັບ' ຈະກຳນົດຜະລິດຕະພັນທີ່ໂປຣໂມຊັນນຳໃຊ້ໄດ້<br />ສຳລັບການອັບເກຣດ/ຫຼຸດລະດັບຜະລິດຕະພັນ, 'ຕ້ອງການ' ສາມາດໃຊ້ເພື່ອຈຳກັດຜະລິດຕະພັນທີ່ກຳລັງຖືກອັບເກຣດມາຈາກ<br />ແລະ ສຳລັບການອັບເກຣດ/ຫຼຸດລະດັບຕົວເລືອກທີ່ຕັ້ງຄ່າໄດ້, ທ່ານສາມາດເລືອກຕົວເລືອກສະເພາະທີ່ຈະນຳໃຊ້ສ່ວນຫຼຸດໄດ້ລຸ່ມນີ້<br />ຖ້າທ່ານຕັ້ງຄ່າມູນຄ່າສ່ວນຫຼຸດ ແລະ ເປີດໃຊ້ການຕໍ່ເນື່ອງ (recurring) ດ້ານເທິງ, ໂປຣໂມຊັນອັບເກຣດຈະໃຫ້ສ່ວນຫຼຸດແບບຕໍ່ເນື່ອງແກ່ຜະລິດຕະພັນຫຼັກນຳ";
