$_ADMINLANG['domainregistrars']['othersettings'] = "ການຕັ້ງຄ່າອື່ນໆ";
$_ADMINLANG['domainregistrars']['pagedesc'] = "ທ່ານສາມາດຕັ້ງຄ່າທີ່ຈຳເປັນເພື່ອເຊື່ອມຕໍ່ກັບຜູ້ໃຫ້ບໍລິການຈົດທະບຽນໂດເມນຂອງທ່ານໄດ້ທີ່ນີ້. ທ່ານສາມາດຕັ້ງຄ່າໄດ້ຫຼາຍກວ່າ 1 ບ່ອນຖ້າທ່ານຕ້ອງການໃຊ້ຜູ້ລົງທະບຽນທີ່ແຕກຕ່າງກັນ ແລະ ສາມາດກຳນົດໄດ້ວ່າ TLD ໃດຈະຖືກມອບໝາຍໃຫ້ຜູ້ລົງທະບຽນໃດໃນສ່ວນການຕັ້ງຄ່າລາຄາໂດເມນ. ເລີ່ມຕົ້ນໂດຍການເລືອກຜູ້ໃຫ້ບໍລິການທີ່ທ່ານຕ້ອງການຕັ້ງຄ່າຈາກເມນູລຸ່ມນີ້.";
