$_ADMINLANG['domainregistrars']['domainsynccrondesc'] = "ໂມດູນຜູ້ລົງທະບຽນນີ້ມີສະຄຣິບຊິງຄ໌ເຊິ່ງສາມາດແລ່ນເປັນໄລຍະເພື່ອຮັບປະກັນວ່າວັນໝົດອາຍຸ, ວັນກຳນົດຊຳລະຖັດໄປ ແລະ ສະຖານະໂດເມນແມ່ນເປັນຂໍ້ມູນປັດຈຸບັນສະເໝີໃນລະບົບ WHMCS ຂອງທ່ານ. ເພື່ອໃຊ້ງານຟີເຈີນີ້, ທ່ານຕ້ອງຕັ້ງຄ່າ Cron ດ້ວຍຄຳສັ່ງລຸ່ມນີ້ເພື່ອໃຫ້ແລ່ນເປັນໄລຍະ (ອາທິດລະ 1 ຫຼື 2 ຄັ້ງກໍພຽງພໍແລ້ວ).";
