# 2FA Security
$_ADMINLANG['twofa']['title'] = "ການຢືນຢັນຕົວຕົນແບບສອງຂັ້ນຕອນ (2FA)";
$_ADMINLANG['twofa']['introtext'] = "ການຢືນຢັນຕົວຕົນແບບສອງຂັ້ນຕອນຊ່ວຍເພີ່ມຄວາມປອດໄພອີກຊັ້ນໜຶ່ງໃຫ້ກັບການເຂົ້າສູ່ລະບົບ. ເມື່ອເປີດໃຊ້ ແລະ ຕັ້ງຄ່າສຳລັບຜູ້ດູແລລະບົບ (ແຕ່ລະຄົນຕ້ອງເປີດໃຊ້ແຍກກັນ), ທຸກໆຄັ້ງທີ່ຜູ້ໃຊ້ນັ້ນເຂົ້າສູ່ລະບົບ ເຂົາເຈົ້າຈະຕ້ອງປ້ອນທັງຊື່ຜູ້ໃຊ້ ແລະ ລະຫັດຜ່ານ ລວມທັງປັດໄຈທີສອງ ເຊັ່ນ ລະຫັດຄວາມປອດໄພ. ພວກເຮົາຮອງຮັບວິທີການຢືນຢັນຕົວຕົນແບບສອງຂັ້ນຕອນທີ່ຫຼາກຫຼາຍລຸ່ມນີ້.";
$_ADMINLANG['twofa']['enable'] = "ເປີດໃຊ້ ".$_ADMINLANG['twofa']['title'];
$_ADMINLANG['twofa']['disable'] = "ປິດໃຊ້ ".$_ADMINLANG['twofa']['title'];
$_ADMINLANG['twofa']['activateintro'] = "ການຢືນຢັນຕົວຕົນແບບສອງຂັ້ນຕອນຊ່ວຍເພີ່ມຄວາມປອດໄພອີກຊັ້ນໜຶ່ງໃຫ້ກັບບັນຊີຂອງທ່ານ. ເມື່ອເປີດໃຊ້ແລ້ວ, ທຸກໆຄັ້ງທີ່ທ່ານເຂົ້າສູ່ລະບົບສ່ວນຜູ້ດູແລຂອງ WHMCS, ທ່ານຈະຕ້ອງປ້ອນທັງຊື່ຜູ້ໃຊ້ ແລະ ລະຫັດຜ່ານ ລວມທັງປັດໄຈທີສອງ ເຊັ່ນ ລະຫັດຄວາມປອດໄພ.";
$_ADMINLANG['twofa']['disableintro'] = "ເພື່ອປິດໃຊ້ ".$_ADMINLANG['twofa']['title']." ກະລຸນາຢືນຢັນລະຫັດຜ່ານຂອງທ່ານໃນຊ່ອງລຸ່ມນີ້.";
$_ADMINLANG['twofa']['choose'] = "ກະລຸນາເລືອກປັດໄຈທີສອງທີ່ທ່ານຕ້ອງການລຸ່ມນີ້.";
$_ADMINLANG['twofa']['enforced'] = "ຜູ້ດູແລລະບົບຂອງທ່ານໄດ້ບັງຄັບໃຫ້ທ່ານຕ້ອງເປີດໃຊ້ ".$_ADMINLANG['twofa']['title']." ກ່ອນທີ່ຈະສາມາດດຳເນີນການຕໍ່ໄດ້. ໜ້ານີ້ຈະແນະນຳທ່ານຜ່ານຂັ້ນຕອນການຕັ້ງຄ່າ.";
