$_ADMINLANG['healthCheck']['permissionCheckConfigFileWritable'] = "ໄຟລ໌ການຕັ້ງຄ່າ (configuration file) ຂອງທ່ານສາມາດຂຽນທັບໄດ້. ນີ້ອາດເປັນຄວາມສ່ຽງດ້ານຄວາມປອດໄພ. ພວກເຮົາແນະນຳໃຫ້ຕັ້ງສິດເປັນ ອ່ານຢ່າງດຽວ (read only).";
$_ADMINLANG['healthCheck']['permissionCheckUnownedDirectories'] = "ໄດເລກທໍຣີຕໍ່ໄປນີ້ຖືກຄອບຄອງໂດຍຜູ້ໃຊ້ອື່ນທີ່ບໍ່ແມ່ນຜູ້ທີ່ກຳລັງແລ່ນ WHMCS. ນີ້ບົ່ງບອກເຖິງການຕັ້ງຄ່າທີ່ອາດຈະບໍ່ປອດໄພ:";
$_ADMINLANG['healthCheck']['permissionCheckUnownedDirectories2'] = "ທ່ານສາມາດຮຽນຮູ້ເພີ່ມເຕີມກ່ຽວກັບເລື່ອງນີ້ໄດ້ໃນ <a :href>ເອກະສານປະກອບ</a> ຂອງພວກເຮົາ.";
$_ADMINLANG['healthCheck']['customTemplates'] = "ການໃຊ້ແມ່ແບບເລີ່ມຕົ້ນ";
$_ADMINLANG['healthCheck']['customTemplatesSuccess'] = "ການຕິດຕັ້ງ WHMCS ຂອງທ່ານກຳລັງໃຊ້ແມ່ແບບທີ່ປັບແຕ່ງເອງ ເຊິ່ງຈະບໍ່ຖືກຂຽນທັບເມື່ອມີການອັບເກຣດ.";
$_ADMINLANG['healthCheck']['customTemplatesFailure'] = "ພວກເຮົາກວດພົບວ່າການຕິດຕັ້ງ WHMCS ຂອງທ່ານກຳລັງໃຊ້ຊື່ແມ່ແບບເລີ່ມຕົ້ນສຳລັບໜຶ່ງແມ່ແບບ ຫຼື ຫຼາຍກວ່ານັ້ນ. ຫາກທ່ານມີການປັບແຕ່ງໃດໆ, ພວກເຮົາແນະນຳຢ່າງຍິ່ງໃຫ້ສ້າງໄດເລກທໍຣີແມ່ແບບໃໝ່ເພື່ອຫຼີກເວັ້ນການສູນເສຍການປັບແຕ່ງຂອງທ່ານໃນຄັ້ງຖັດໄປທີ່ທ່ານອັບເກຣດ.<br /><br />ປັດຈຸບັນທ່ານກຳລັງໃຊ້ແມ່ແບບເລີ່ມຕົ້ນໃນຕຳແໜ່ງຕໍ່ໄປນີ້:";
$_ADMINLANG['healthCheck']['customTemplatesFailure2'] = "ກະລຸນາກວດສອບ <a :href>ເອກະສານປະກອບ</a> ຂອງພວກເຮົາກ່ຽວກັບການສ້າງທີມທີ່ປັບແຕ່ງເອງເພື່ອຂໍຄວາມຊ່ວຍເຫຼືອ.";
$_ADMINLANG['healthCheck']['phpVersion'] = "ເວີຊັນ PHP";
$_ADMINLANG['healthCheck']['phpVersionWhmcsSupported'] = "PHP ເວີຊັນ <strong>:version</strong> ຂອງທ່ານຖືກຮອງຮັບໂດຍ WHMCS. ";
$_ADMINLANG['healthCheck']['phpVersionWhmcsUnsupported'] = "PHP ເວີຊັນ <strong>:version</strong> ຂອງທ່ານບໍ່ຖືກຮອງຮັບໂດຍ WHMCS. WHMCS ຕ້ອງການ PHP ເວີຊັນຢ່າງໜ້ອຍ 5.3.7.";
$_ADMINLANG['healthCheck']['phpVersionPhpSupported'] = "ເວີຊັນ PHP ຂອງທ່ານໄດ້ຮັບການຮອງຮັບຢ່າງເປັນທາງການສຳລັບທັງການແກ້ໄຂບັກ ແລະ ການອັບເດດຄວາມປອດໄພ.";
$_ADMINLANG['healthCheck']['phpVersionPhpSecurityUpdatesOnly'] = "PHP ສາຍເວີຊັນ :version ຈະບໍ່ໄດ້ຮັບການແກ້ໄຂບັກປົກກະຕິອີກຕໍ່ໄປ ແລະ ຈະໄດ້ຮັບພຽງແຕ່ການອັບເດດຄວາມປອດໄພທີ່ສຳຄັນຈົນກວ່າຈະໝົດອາຍຸການໃຊ້ງານ. ກະລຸນາເບິ່ງ <a href=\"https://docs.whmcs.com/System_Environment_Guide#PHP_Version\">ເອກະສານປະກອບ</a> ຂອງພວກເຮົາສຳລັບຂໍ້ມູນເພີ່ມເຕີມ.";
$_ADMINLANG['healthCheck']['phpVersionPhpUnsupported'] = "PHP ສາຍເວີຊັນ :version ໄດ້ໝົດອາຍຸການໃຊ້ງານແລ້ວ ແລະ ຈະບໍ່ໄດ້ຮັບການແກ້ໄຂບັກ ຫຼື ຄວາມປອດໄພທີ່ສຳຄັນ. ກະລຸນາເບິ່ງ <a href=\"https://docs.whmcs.com/System_Environment_Guide#PHP_Version\">ເອກະສານປະກອບ</a> ຂອງພວກເຮົາສຳລັບຂໍ້ມູນເພີ່ມເຕີມ.";
$_ADMINLANG['healthCheck']['requiredPhpExtensions'] = "ສ່ວນຂະຫຍາຍ (Extensions) PHP ທີ່ຈຳເປັນ";
$_ADMINLANG['healthCheck']['requiredPhpExtensionsSuccess'] = "ການຕິດຕັ້ງ PHP ຂອງທ່ານມີສ່ວນຂະຫຍາຍທັງໝົດທີ່ຈຳເປັນສຳລັບການເຮັດວຽກຂອງ WHMCS ແລ້ວ.";
$_ADMINLANG['healthCheck']['requiredPhpExtensionsFailure'] = "ສ່ວນຂະຫຍາຍ PHP ຕໍ່ໄປນີ້ແມ່ນຈຳເປັນເພື່ອໃຫ້ WHMCS ສາມາດເຮັດວຽກໄດ້ຢ່າງເຕັມຮູບແບບ:";
$_ADMINLANG['healthCheck']['requiredPhpExtensionsFailure2'] = "ກະລຸນາກວດສອບ <a :href>ຄວາມຕ້ອງການຂອງລະບົບ</a> WHMCS ປັດຈຸບັນ ແລະ ຮັບປະກັນວ່າລະບົບຂອງທ່ານກົງຕາມນັ້ນ.";
$_ADMINLANG['healthCheck']['recommendedPhpExtensions'] = "ສ່ວນຂະຫຍາຍ PHP ທີ່ແນະນຳ";
$_ADMINLANG['healthCheck']['recommendedPhpExtensionsSuccess'] = "ການຕິດຕັ້ງ PHP ຂອງທ່ານມີສ່ວນຂະຫຍາຍທີ່ແນະນຳທັງໝົດທີ່ຕ້ອງການໂດຍບາງໂມດູນ ແລະ ສ່ວນເສີມຂອງ WHMCS.";
$_ADMINLANG['healthCheck']['recommendedPhpExtensionsFailure'] = "ສ່ວນຂະຫຍາຍ PHP ຕໍ່ໄປນີ້ແມ່ນໄດ້ຮັບການແນະນຳເພື່ອປະສິດທິພາບທີ່ດີທີ່ສຸດ ແລະ ການເຮັດວຽກທີ່ບໍ່ມີບັນຫາ. ເຖິງແມ່ນວ່າມັນເປັນທາງເລືອກສຳລັບຟັງຊັນຫຼັກຂອງ WHMCS, ແຕ່ບາງໂມດູນ ແລະ ສ່ວນເສີມອາດຈະຕ້ອງການພວກມັນເພື່ອເຮັດວຽກໄດ້ຕາມທີ່ກຳນົດໄວ້:";
$_ADMINLANG['healthCheck']['recommendedPhpExtensionsFailure2'] = "ກະລຸນາກວດສອບ <a :href>ຄຳແນະນຳຂອງລະບົບ</a> ປັດຈຸບັນ ແລະ ຄົ້ນຫາເອກະສານປະກອບຂອງພວກເຮົາສຳລັບໂມດູນສະເພາະທີ່ທ່ານໃຊ້ເພື່ອຮຽນຮູ້ເພີ່ມເຕີມ.";
$_ADMINLANG['healthCheck']['requiredPhpFunctions'] = "ຟັງຊັນ PHP ທີ່ຈຳເປັນ";
$_ADMINLANG['healthCheck']['requiredPhpFunctionsSuccess'] = "ການຕິດຕັ້ງ PHP ຂອງທ່ານມີຟັງຊັນທີ່ຈຳເປັນທັງໝົດເພື່ອໃຫ້ WHMCS ເຮັດວຽກໄດ້.";
$_ADMINLANG['healthCheck']['requiredPhpFunctionsFailure'] = "ຟັງຊັນ PHP ຕໍ່ໄປນີ້ຕ້ອງໄດ້ຮັບການເປີດໃຊ້ເພື່ອໃຫ້ WHMCS ສາມາດເຮັດວຽກໄດ້ຢ່າງເຕັມຮູບແບບຕາມທີ່ກຳນົດໄວ້:";
$_ADMINLANG['healthCheck']['requiredPhpFunctionsFailure2'] = "ຟັງຊັນເຫຼົ່ານີ້ຖືກປິດໃຊ້ງານຢູ່ໃນໄຟລ໌ php.ini ຂອງທ່ານ, ພວກເຮົາແນະນຳໃຫ້ທ່ານຕິດຕໍ່ຜູ້ດູແລລະບົບຂອງທ່ານເພື່ອເປີດໃຊ້ພວກມັນ.";
$_ADMINLANG['healthCheck']['menuTitle'] = "ສະຖານະສຸຂະພາບຂອງລະບົບ";
$_ADMINLANG['healthCheck']['readMore'] = "ອ່ານເພີ່ມເຕີມ";
$_ADMINLANG['healthCheck']['phpMemory'] = "ຂີດຈຳກັດໜ່ວຍຄວາມຈຳ PHP (Memory Limit)";
$_ADMINLANG['healthCheck']['phpMemoryTooLow'] = "ຄ່າ memory_limit ຂອງ PHP ຂອງທ່ານແມ່ນ <strong>:memory_limit</strong> ເຊິ່ງຕ່ຳເກີນໄປ. WHMCS ຕ້ອງການຂັ້ນຕ່ຳ 64M. ທ່ານສາມາດປ່ຽນສິ່ງນີ້ໃນ php.ini ຂອງທ່ານດ້ວຍ <a :href>set_ini command</a>.";
$_ADMINLANG['healthCheck']['phpMemoryLow'] = "ຄ່າ memory_limit ຂອງ PHP ຂອງທ່ານແມ່ນ <strong>:memory_limit</strong> ເຊິ່ງຕ່ຳກວ່າທີ່ແນະນຳ. WHMCS ແນະນຳຢ່າງໜ້ອຍ 128M, ແນວໃດກໍຕາມຄ່າຂອງທ່ານຍັງສູງກວ່າຄວາມຕ້ອງການຂັ້ນຕ່ຳ 64M. ທ່ານສາມາດປ່ຽນສິ່ງນີ້ໃນ php.ini ຂອງທ່ານດ້ວຍ <a :href>set_ini command</a>.";
$_ADMINLANG['healthCheck']['phpMemorySuccess'] = "ຄ່າ memory_limit ຂອງ PHP ຂອງທ່ານແມ່ນ <strong>:memory_limit</strong> ເຊິ່ງກົງຕາມຄ່າທີ່ແນະນຳ 128M ແລ້ວ.";
$_ADMINLANG['healthCheck']['news'] = "ຂ່າວສານ ແລະ ປະກາດຫຼ້າສຸດ";
$_ADMINLANG['healthCheck']['errorDisplay'] = "ການລາຍງານຂໍ້ຜິດພາດ (Error Reporting)";
$_ADMINLANG['healthCheck']['errorDisplaySuccess'] = "ລະບົບຂອງທ່ານບໍ່ໄດ້ຕັ້ງຄ່າໃຫ້ສະແດງຂໍ້ຜິດພາດໃນປັດຈຸບັນ.";
$_ADMINLANG['healthCheck']['errorDisplayFailure'] = "ລະບົບຂອງທ່ານຖືກຕັ້ງຄ່າໃຫ້ສະແດງຂໍ້ຜິດພາດ. ເຖິງແມ່ນວ່ານີ້ຈະມີປະໂຫຍດສຳລັບບາງສະຖານະການດີບັກ, ແຕ່ມັນສາມາດລົບກວນການເຮັດວຽກບາງຢ່າງ ແລະ ເປັນຄວາມສ່ຽງດ້ານຄວາມປອດໄພ. ສຳລັບຂໍ້ມູນເພີ່ມເຕີມກະລຸນາເບິ່ງ <a :href>ເອກະສານປະກອບ</a> ຂອງພວກເຮົາ.";
$_ADMINLANG['healthCheck']['errorLevels'] = "ລະດັບຂໍ້ຜິດພາດ PHP";
$_ADMINLANG['healthCheck']['errorLevelsSuccess'] = "ລະບົບຂອງທ່ານຖືກຕັ້ງຄ່າເພື່ອບໍ່ໃຫ້ບັນທຶກລະດັບຂໍ້ຜິດພາດທີ່ບໍ່ຈຳເປັນ.";
$_ADMINLANG['healthCheck']['errorLevelsFailure'] = "ລະບົບຂອງທ່ານຖືກຕັ້ງຄ່າໃຫ້ບັນທຶກລະດັບຂໍ້ຜິດພາດທີ່ບໍ່ຈຳເປັນ. ການລາຍງານລະດັບຂໍ້ຜິດພາດທີ່ບັນທຶກ E_NOTICE ແລະ E_WARNING ສາມາດລົບກວນການເຮັດວຽກບາງຢ່າງ ແລະ ເປັນຄວາມສ່ຽງດ້ານຄວາມປອດໄພ. ສຳລັບຂໍ້ມູນເພີ່ມເຕີມກະລຸນາເບິ່ງ <a :href>ເອກະສານປະກອບ</a> ຂອງພວກເຮົາ.";

$_ADMINLANG['healthCheck']['curlSslSupport'] = "ການຮອງຮັບ SSL ໃນ cURL";
$_ADMINLANG['healthCheck']['curlSslSupportSuccess'] = "cURL ລາຍງານວ່າມັນຮອງຮັບ SSL";
$_ADMINLANG['healthCheck']['curlSslSupportFailure'] = "cURL ລາຍງານວ່າມັນບໍ່ຮອງຮັບ SSL. ກະລຸນາກວດສອບໃຫ້ແນ່ໃຈວ່າ cURL ຖືກຕິດຕັ້ງ ແລະ ຮອງຮັບ SSL ຕາມທີ່ລະບຸໃນ <a :href>ຄວາມຕ້ອງການຂອງລະບົບ</a>";

$_ADMINLANG['healthCheck']['curlSecureTlsSupport'] = "ການຮອງຮັບ Secure TLS ໃນ cURL";
$_ADMINLANG['healthCheck']['curlSecureTlsSupportSuccess'] = "cURL ລາຍງານວ່າມັນຮອງຮັບ Secure TLS 1.1 ແລະ 1.2";
$_ADMINLANG['healthCheck']['curlSecureTlsSupportFailure'] = "cURL ລາຍງານວ່າມັນບໍ່ຮອງຮັບ Secure TLS 1.1 ແລະ 1.2. ກະລຸນາກວດສອບໃຫ້ແນ່ໃຈວ່າໄລບຣາຣີ SSL ທີ່ຮອງຮັບ TLS 1.1 ແລະ 1.2 ໄດ້ຖືກຕິດຕັ້ງ ແລະ ຮອງຮັບໂດຍ cURL.";

$_ADMINLANG['healthCheck']['phpSessionSupport'] = "ການຮອງຮັບ PHP Session";
$_ADMINLANG['healthCheck']['phpSessionSupportEnabled'] = "ການຮອງຮັບ PHP session ຖືກເປີດໃຊ້ແລ້ວ.";
$_ADMINLANG['healthCheck']['phpSessionSupportDisabled'] = "ການຮອງຮັບ PHP session ຖືກປິດໃຊ້ງານ. ສິ່ງນີ້ຈະປ້ອງກັນບໍ່ໃຫ້ WHMCS ຈົດຈຳການເຂົ້າສູ່ລະບົບຂອງຜູ້ໃຊ້. ກະລຸນາຕິດຕໍ່ຜູ້ດູແລລະບົບຂອງທ່ານເພື່ອເປີດໃຊ້ສ່ວນຂະຫຍາຍ PHP session.";
$_ADMINLANG['healthCheck']['phpSessionSupportAutoStartEnabled'] = "Session autostart ຖືກເປີດໃຊ້ແລ້ວ. ສິ່ງນີ້ຈະປ້ອງກັນບໍ່ໃຫ້ WHMCS ຈົດຈຳການເຂົ້າສູ່ລະບົບຂອງຜູ້ໃຊ້. ກະລຸນາປິດການຕັ້ງຄ່າ <strong>session.auto_start</strong> ໃນ PHP.";
$_ADMINLANG['healthCheck']['phpSessionSupportAutoStartDisabled'] = "Session autostart ຖືກປິດໃຊ້ງານແລ້ວ.";
$_ADMINLANG['healthCheck']['phpSessionSupportSavePathIsWritable'] = "ເສັ້ນທາງບັນທຶກ PHP session <strong>:path</strong> ສາມາດຂຽນໄດ້. ";
$_ADMINLANG['healthCheck']['phpSessionSupportSavePathIsNotWritable'] = "ເສັ້ນທາງບັນທຶກ PHP session <strong>:path</strong> ບໍ່ສາມາດຂຽນໄດ້. ກະລຸນາກວດສອບການຕັ້ງຄ່າ <strong>session.save_path</strong> ໃນ PHP ຫຼື ຕິດຕໍ່ຜູ້ດູແລລະບົບຂອງທ່ານ";
$_ADMINLANG['healthCheck']['emailEncryption'] = "ການເຂົ້າລະຫັດການສົ່ງອີເມລ";
$_ADMINLANG['healthCheck']['emailEncryptionSuccess'] = "ການຕັ້ງຄ່າ SMTP ຂອງທ່ານກຳລັງໃຊ້ການເຂົ້າລະຫັດເພື່ອຮັບປະກັນວ່າຂໍ້ມູນທີ່ລະອຽດອ່ອນໃນອີເມລຈະບໍ່ຖືກຮົ່ວໄຫຼໃນລະຫວ່າງການສົ່ງໄປຫາຕົວແທນການສົ່ງເມລຂອງທ່ານ.";
$_ADMINLANG['healthCheck']['emailEncryptionWarning'] = "ທ່ານບໍ່ໄດ້ເປີດໃຊ້ການເຂົ້າລະຫັດ SSL ຫຼື TLS ສຳລັບການຕັ້ງຄ່າອີເມລ SMTP ຂອງທ່ານ. ສິ່ງນີ້ເພີ່ມໂອກາດທີ່ຂໍ້ມູນລະອຽດອ່ອນທີ່ສົ່ງຫາລູກຄ້າຈະຮົ່ວໄຫຼໃນລະຫວ່າງຂະບວນການສົ່ງເມລ. ພວກເຮົາແນະນຳໃຫ້ໃຊ້ການເຂົ້າລະຫັດເພື່ອຢືນຢັນ ແລະ ຮັກສາຄວາມປອດໄພຂອງການສື່ສານຂອງທ່ານ.";

$_ADMINLANG['healthCheck']['dbVersionTitle'] = "ເວີຊັນຂອງ Database Engine";
$_ADMINLANG['healthCheck']['dbVersionIsUpToDate'] = "ທ່ານກຳລັງໃຊ້ :dbname ເວີຊັນ :currentversion. ເວີຊັນນີ້ຮອງຮັບທຸກຟີເຈີທີ່ຈຳເປັນສຳລັບຄວາມເຂົ້າກັນໄດ້ກັບ WHMCS.";
$_ADMINLANG['healthCheck']['dbVersionUpgradeRequired'] = "ທ່ານກຳລັງໃຊ້ :dbname ເວີຊັນ :currentversion. ເວີຊັນນີ້ໝົດອາຍຸການໃຊ້ງານແລ້ວ. ການແລ່ນ WHMCS ໃນສະພາບແວດລ້ອມນີ້ແມ່ນບໍ່ໄດ້ຮັບການຮອງຮັບ. ກະລຸນາອັບເກຣດເປັນ MySQL ຫຼື MariaDB ເວີຊັນຫຼ້າສຸດ.";
$_ADMINLANG['healthCheck']['dbVersionUpgradeRecommended'] = "ທ່ານກຳລັງໃຊ້ :dbname ເວີຊັນ :currentversion. ແນະນຳໃຫ້ໃຊ້ :dbname ເວີຊັນ :recommendedversion ຫຼື ສູງກວ່າເພື່ອຄວາມເຂົ້າກັນໄດ້ຢ່າງເຕັມທີ່ກັບການຈັດເກັບຂໍ້ມູນ Unicode.";
$_ADMINLANG['healthCheck']['dbMinorVersionUpgradeRequired'] = "ທ່ານກຳລັງໃຊ້ :dbname ເວີຊັນ :currentversion. ຕ້ອງການ :dbname ເວີຊັນ :requiredVersion ຫຼື ສູງກວ່າເພື່ອຄວາມເຂົ້າກັນໄດ້ຢ່າງເຕັມທີ່.";

$_ADMINLANG['healthCheck']['dbCollationsTitle'] = "Database Collations";
$_ADMINLANG['healthCheck']['dbCollationsOk'] = "ທຸກຕາຕະລາງ ແລະ ຄໍລຳໃນຖານຂໍ້ມູນໃຊ້ collation ດຽວກັນຕາມທີ່ແນະນຳ (:collationsText).";
$_ADMINLANG['healthCheck']['dbCollationsNotOk'] = "ໜຶ່ງຕາຕະລາງ ຫຼື ຫຼາຍກວ່ານັ້ນ ແລະ/ຫຼື ຄໍລຳໃນຖານຂໍ້ມູນກຳລັງໃຊ້ collation ແບບເກົ່າ ຫຼື ບໍ່ກົງກັນ. ພວກເຮົາແນະນຳໃຫ້ໃຊ້ collation <strong>:collationsText</strong> ສຳລັບທຸກຕາຕະລາງ ແລະ ຄໍລຳເພື່ອຮັບປະກັນການເຮັດວຽກທີ່ຖືກຕ້ອງ. ສຳລັບຂໍ້ມູນເພີ່ມເຕີມກະລຸນາເບິ່ງ <a :href>ເອກະສານປະກອບ</a> ຂອງພວກເຮົາ.";
$_ADMINLANG['healthCheck']['updaterTitle'] = "ຄວາມຕ້ອງການສຳລັບການອັບເດດອັດຕະໂນມັດ";
$_ADMINLANG['healthCheck']['updaterFopen'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໃຫ້ເປີດໃຊ້ allow_url_fopen ໃນການຕັ້ງຄ່າ PHP ຂອງທ່ານ.";
$_ADMINLANG['healthCheck']['maxExecutionTime'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໃຫ້ຕັ້ງຄ່າ max_execution_time ເປັນ :required_value ວິນາທີ ຫຼື ສູງກວ່າໃນການຕັ້ງຄ່າ PHP ຂອງທ່ານ.";
$_ADMINLANG['healthCheck']['updaterZip'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໂມດູນ Zip ຫຼື ຟັງຊັນ proc_open ທີ່ມີໃຫ້ໃຊ້ໃນ PHP.";
$_ADMINLANG['healthCheck']['updaterChmod'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການຟັງຊັນ chmod ທີ່ມີໃຫ້ໃຊ້ໃນ PHP.";
$_ADMINLANG['healthCheck']['updaterEscapeShellArg'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການຟັງຊັນ escapeshellarg ທີ່ມີໃຫ້ໃຊ້ໃນ PHP.";
$_ADMINLANG['healthCheck']['updaterDisabledFunctions'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໃຫ້ເປີດໃຊ້ຟັງຊັນ PHP ຕໍ່ໄປນີ້: :functions.";
$_ADMINLANG['healthCheck']['updaterVendorWriteable'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໃຫ້ໄດເລກທໍຣີ whmcs /vendor/whmcs/whmcs/ ສາມາດຂຽນໄດ້.";
$_ADMINLANG['healthCheck']['updaterTempSet'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໄດເລກທໍຣີທີ່ຂຽນໄດ້ສຳລັບການພັກໄຟລ໌ໃນລະຫວ່າງການອັບເດດ. ທ່ານຕ້ອງລະບຸໄດເລກທໍຣີຜ່ານ Updater Configuration ກ່ອນຈຶ່ງຈະສາມາດອັບເດດໄດ້.";
$_ADMINLANG['healthCheck']['updaterTempWriteable'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໄດເລກທໍຣີທີ່ຂຽນໄດ້ສຳລັບການພັກໄຟລ໌ໃນລະຫວ່າງການອັບເດດ. ເສັ້ນທາງຊົ່ວຄາວທີ່ຕັ້ງໄວ້ໃນປັດຈຸບັນບໍ່ສາມາດຂຽນຂໍ້ມູນລົງໄດ້. ກະລຸນາກວດສອບ ແລະ ແກ້ໄຂສິດການເຂົ້າເຖິງ.";
$_ADMINLANG['healthCheck']['updaterGeneralMemoryLimit'] = "ການອັບເດດອັດຕະໂນມັດຕ້ອງການໜ່ວຍຄວາມຈຳຢ່າງໜ້ອຍ :memoryLimitRequired ສຳລັບການປະມວນຜົນ PHP. ການຕັ້ງຄ່າ memory_limit ຂອງ PHP ຂອງທ່ານໃນປັດຈຸບັນແມ່ນຕ່ຳກວ່ານີ້. ເພື່ອອັບເດດ, ກະລຸນາເພີ່ມ memory_limit ໃນການຕັ້ງຄ່າ PHP ຂອງທ່ານເປັນ :memoryLimitRequired ຫຼື ສູງກວ່າ.";
$_ADMINLANG['healthCheck']['updaterVersionMemoryLimit'] = "ການອັບເດດອັດຕະໂນມັດເປັນເວີຊັນ :updateVersion ຕ້ອງການໜ່ວຍຄວາມຈຳຢ່າງໜ້ອຍ :memoryLimitRequired ສຳລັບການປະມວນຜົນ PHP. ການຕັ້ງຄ່າ memory_limit ຂອງ PHP ຂອງທ່ານໃນປັດຈຸບັນແມ່ນຕ່ຳກວ່ານີ້. ເພື່ອອັບເດດ, ກະລຸນາເພີ່ມ memory_limit ໃນການຕັ້ງຄ່າ PHP ຂອງທ່ານເປັນ :memoryLimitRequired ຫຼື ສູງກວ່າ.";
$_ADMINLANG['healthCheck']['updaterSuccess'] = "ສະພາບແວດລ້ອມຂອງທ່ານເບິ່ງຄືວ່າກົງຕາມຄວາມຕ້ອງການຂັ້ນຕ່ຳສຳລັບການອັບເດດອັດຕະໂນມັດ. ເພື່ອອັບເດດ, ທ່ານຕ້ອງໝັ້ນໃຈວ່າມີພື້ນທີ່ວ່າງໃນດິດຢ່າງໜ້ອຍ 250MB.";
$_ADMINLANG['healthCheck']['updaterIoncubeLoaderMismatch'] = "ລະບົບຂອງທ່ານມີ ionCube Loader :loaderVersionInstalled. ກະລຸນາຕິດຕັ້ງ ionCube Loader :loaderVersionRequired ຫຼື ສູງກວ່າເພື່ອອັບເດດເປັນ WHMCS ເວີຊັນ :updateVersion. <a href=\"https://docs.whmcs.com/System_Environment_Guide#IonCube_Version\">ຮຽນຮູ້ເພີ່ມເຕີມ</a>";

$_ADMINLANG['appLinks']['description'] = "Application Links ຊ່ວຍໃຫ້ທ່ານສາມາດໃຫ້ສິດການເຂົ້າເຖິງບັນຊີຜູ້ໃຊ້ໃນ WHMCS ຈາກແອັບພລິເຄຊັນພາຍນອກ.";
$_ADMINLANG['appLinks']['description2'] = "ທຸກແອັບພລິເຄຊັນທີ່ຮອງຮັບ Application Linking ຖືກສະແດງລາຍຊື່ໄວ້ລຸ່ມນີ້ ແລະ ສາມາດເປີດ/ປິດໃຊ້ງານໄດ້ງ່າຍໆໂດຍການປ່ຽນຕົວເລືອກລຸ່ມນີ້. ການເປີດໃຊ້ application linking ສຳລັບແອັບພລິເຄຊັນຈະເຮັດໃຫ້ເກີດຂະບວນການໃນເບື້ອງຫຼັງເພື່ອສ້າງລິ້ງແອັບພລິເຄຊັນເລີ່ມຕົ້ນ. ກະລຸນາລໍຖ້າປະມານ 30 ນາທີເພື່ອໃຫ້ມີຜົນກັບທຸກຜະລິດຕະພັນ/ບໍລິການ.";
