$_ADMINLANG['healthCheck']['sslIsRecommended'] = "ສິ່ງນີ້ຈະປ້ອງກັນບາງຟີເຈີ ເຊັ່ນ OpenID Connect ບໍ່ໃຫ້ເຮັດວຽກ. ນອກຈາກນີ້ຍັງອາດສົ່ງຜົນກະທົບຕໍ່ຄວາມສາມາດໃນການໄດ້ຮັບ PCI ຫຼື ການຢັ້ງຢືນອື່ນໆ.";
