$_ADMINLANG['healthCheck']['phpTimezoneNotSet'] = "ສະພາບແວດລ້ອມ PHP ຂອງທ່ານບໍ່ມີການຕັ້ງຄ່າເຂດເວລາທີ່ຖືກຕ້ອງ. ກະລຸນາຕັ້ງຄ່າ date.timezone ໃນ php.ini ເພື່ອຮັບປະກັນການປະມວນຜົນວັນທີ ແລະ ເວລາທີ່ຖືກຕ້ອງ. ຫາກມີການຕັ້ງຄ່າ date.timezone ໃນ php.ini ແລ້ວແຕ່ຍັງເຫັນຄຳເຕືອນນີ້, ກະລຸນາກວດສອບຕົວສະກົດຂອງເຂດເວລາ.";

