$_ADMINLANG['phpCompatUtil']['title'] = "ຄວາມເຂົ້າກັນໄດ້ຂອງເວີຊັນ PHP";
$_ADMINLANG['phpCompatUtil']['compatUtilDesc'] = "ເຄື່ອງມືນີ້ຈະກວດສອບ WHMCS ຂອງທ່ານສຳລັບໄຟລ໌ທີ່ເຂົ້າລະຫັດດ້ວຍ ionCube ແລະ ສ້າງລາຍງານການປະເມີນ.<br/>ການປະເມີນຈະໃຫ້ພາບລວມຂອງຄວາມເຂົ້າກັນໄດ້ຂອງ PHP ທີ່ກ່ຽວຂ້ອງກັບໄຟລ໌ທີ່ເຂົ້າລະຫັດຂອງທ່ານ ເພື່ອໃຫ້ທ່ານສາມາດແກ້ໄຂບັນຫາທີ່ອາດຈະເກີດຂຶ້ນກ່ອນທີ່ຈະອັບເດດເປັນ PHP ເວີຊັນອື່ນ.";
$_ADMINLANG['phpCompatUtil']['report'] = "ລາຍງານການປະເມີນ";
$_ADMINLANG['phpCompatUtil']['scanError'] = "ເກີດຂໍ້ຜິດພາດໃນຂະນະທີ່ສ້າງລາຍງານການປະເມີນ.";
$_ADMINLANG['phpCompatUtil']['file'] = "ໄຟລ໌";
$_ADMINLANG['phpCompatUtil']['updated'] = "ອັບເດດແລ້ວ";
$_ADMINLANG['phpCompatUtil']['never'] = "ບໍ່ເຄີຍ";
$_ADMINLANG['phpCompatUtil']['scan'] = "ສະແກນ";
$_ADMINLANG['phpCompatUtil']['rescan'] = "ສະແກນໃໝ່";
$_ADMINLANG['phpCompatUtil']['clickToScan'] = "ຄລິກສະແກນເພື່ອສ້າງລາຍງານການປະເມີນ.";
$_ADMINLANG['phpCompatUtil']['compatNoDesc'] = "ໄຟລ໌ເຫຼົ່ານີ້ບໍ່ສາມາດຖອດລະຫັດໂດຍ ionCube Loader ສຳລັບ PHP ເວີຊັນທີ່ລະບຸໄດ້. ຫາກທ່ານຕ້ອງການໃຊ້ PHP ເວີຊັນນີ້, ທ່ານຕ້ອງຕິດຕໍ່ຜູ້ພັດທະນາຕົ້ນສະບັບເພື່ອຂໍເວີຊັນທີ່ເຂົ້າລະຫັດໃຫ້ເຂົ້າກັນໄດ້ກັບ PHP ເວີຊັນທີ່ທ່ານຕ້ອງການ.";
$_ADMINLANG['phpCompatUtil']['compatNoTitle'] = "ການເຂົ້າລະຫັດທີ່ບໍ່ເຂົ້າກັນ";
$_ADMINLANG['phpCompatUtil']['compatUnknownDesc1'] = "ບໍ່ສາມາດກຳນົດສະພາບແວດລ້ອມ PHP ທີ່ຮອງຮັບສຳລັບໄຟລ໌ທີ່ເຂົ້າລະຫັດເຫຼົ່ານີ້ໄດ້. ຫາກທ່ານໄດ້ຮັບໄຟລ໌ເຫຼົ່ານີ້ຫຼັງຈາກເດືອນກັນຍາ 2016, ພວກມັນອາດຈະສາມາດຖອດລະຫັດດ້ວຍ PHP ເວີຊັນທີ່ເລືອກໄດ້. ຢ່າງໃດກໍ່ຕາມ, ພວກເຮົາແນະນຳໃຫ້ຕິດຕໍ່ຜູ້ພັດທະນາຕົ້ນສະບັບເພື່ອຢືນຢັນຄວາມເຂົ້າກັນໄດ້ກ່ອນທີ່ຈະອັບເກຣດ.";
$_ADMINLANG['phpCompatUtil']['compatUnknownDesc2'] = "ໄຟລ໌ທີ່ເຂົ້າລະຫັດໂດຍໃຊ້ຕົວເຂົ້າລະຫັດ V9 ຫຼື V10 (ໂດຍບໍ່ມີການລວມກຸ່ມ) ບໍ່ສາມາດແຍກແຍະໄດ້ ແລະ ດັ່ງນັ້ນຈຶ່ງເປັນໄປບໍ່ໄດ້ທີ່ພວກເຮົາຈະຢືນຢັນຄວາມເຂົ້າກັນໄດ້. ຫາກໄດ້ຮັບໄຟລ໌ກ່ອນເດືອນມີນາ 2018, ມີຄວາມເປັນໄປໄດ້ສູງວ່າພວກມັນຖືກເຂົ້າລະຫັດດ້ວຍ ionCube V9 ຫຼື ເກົ່າກວ່າ ແລະ ຈະບໍ່ເຂົ້າກັນໄດ້ກັບ PHP ເວີຊັນທີ່ເລືອກ. ພວກເຮົາແນະນຳໃຫ້ຕິດຕໍ່ຜູ້ພັດທະນາຕົ້ນສະບັບເພື່ອຢືນຢັນຄວາມເຂົ້າກັນໄດ້ກ່ອນທີ່ຈະອັບເກຣດ.";
$_ADMINLANG['phpCompatUtil']['compatUnknownTitle'] = "ບໍ່ຊາບຄວາມເຂົ້າກັນໄດ້ຂອງການເຂົ້າລະຫັດ";
$_ADMINLANG['phpCompatUtil']['compatYesDesc'] = "ໄຟລ໌ເຫຼົ່ານີ້ສາມາດຖອດລະຫັດໂດຍ ionCube Loader ສຳລັບ PHP ເວີຊັນທີ່ລະບຸໄດ້. ສິ່ງນີ້ຖືກກຳນົດໂດຍລາຍເຊັນການເຂົ້າລະຫັດ ionCube ຫຼື ຂໍ້ມູນສະເພາະທີ່ຝັງຢູ່ໃນນັ້ນ.";
