$_ADMINLANG['whmimport']['title'] = "ນຳເຂົ້າໂດເມນຈາກ cPanel/WHM";
$_ADMINLANG['whmimport']['desc'] = "ສະຄຣິບນຳເຂົ້າ WHM ນີ້ສາມາດຊ່ວຍປະຢັດເວລາໃຫ້ທ່ານໄດ້ຫຼາຍຊົ່ວໂມງ. ມັນຈະນຳເຂົ້າໂດເມນ ແລະ ຊື່ຜູ້ໃຊ້ຈາກເຊີບເວີ cPanel ຂອງທ່ານໂດຍອັດຕະໂນມັດ ເພື່ອຫຼຸດຜ່ອນການປ້ອນຂໍ້ມູນດ້ວຍຕົນເອງເຂົ້າໃນ WHMCS.";
$_ADMINLANG['whmimport']['descPkgSetup'] = "ທ່ານຕ້ອງແນ່ໃຈວ່າມີການຕັ້ງຄ່າແພັກເກັດສຳລັບແຕ່ລະຊື່ແພັກເກັດທີ່ໃຊ້ຢູ່ໃນເຊີບເວີໂດຍບັນຊີທີ່ທ່ານກຳລັງຈະນຳເຂົ້າ ກ່ອນທີ່ຈະດຳເນີນການນຳເຂົ້າ ເພາະ WHMCS ຈະພະຍາຍາມກຳນົດບັນຊີໃຫ້ກັບແພັກເກັດໂດຍອັດຕະໂນມັດຕາມຊື່ນີ້. ບັນຊີໃດທີ່ບໍ່ພົບແພັກເກັດທີ່ກົງກັນຈະຖືກລາຍງານໃນຕອນທ້າຍເພື່ອໃຫ້ປ້ອນຂໍ້ມູນດ້ວຍຕົນເອງ.";
$_ADMINLANG['whmimport']['descBeginChoosing'] = "ເລີ່ມຕົ້ນໂດຍການເລືອກເຊີບເວີ cPanel ທີ່ທ່ານຕ້ອງການນຳເຂົ້າຈາກຂ້າງລຸ່ມ, ແລ້ວຄລິກ Get Account List.";
