$_ADMINLANG['marketConnect']['weebly']['learn']['headline'] = "ເຄື່ອງມືສ້າງເວັບໄຊທີ່ໃຊ້ງ່າຍ ແລະ ຊົງພະລັງ";
$_ADMINLANG['marketConnect']['weebly']['learn']['tagline'] = "ຊ່ວຍໃຫ້ລູກຄ້າຂອງທ່ານສ້າງເວັບໄຊທີ່ເບິ່ງເປັນມືອາຊີບໄດ້ໂດຍບໍ່ຕ້ອງມີທັກສະທາງເຕັກນິກ.";
$_ADMINLANG['marketConnect']['weebly']['learn']['description1'] = "ເຄື່ອງມືສ້າງເວັບໄຊແບບລາກ ແລະ ວາງ ຂອງ Weebly ເຮັດໃຫ້ການສ້າງເວັບໄຊທີ່ຊົງພະລັງ ແລະ ເປັນມືອາຊີບເປັນເລື່ອງງ່າຍ ໂດຍບໍ່ຕ້ອງມີທັກສະທາງເຕັກນິກໃດໆ.";
$_ADMINLANG['marketConnect']['weebly']['learn']['description2'] = "ດ້ວຍຮູບແບບທີ່ທັນສະໄໝ ແລະ ຮອງຮັບການສະແດງຜົນທຸກອຸປະກອນ, ລູກຄ້າຂອງທ່ານສາມາດສ້າງຮ້ານຄ້າອອນໄລນ໌, ບລັອກ ຫຼື ເວັບໄຊທີ່ຈະເບິ່ງສວຍງາມໃນທຸກອຸປະກອນ.";
$_ADMINLANG['marketConnect']['weebly']['learn']['description3'] = "Weebly ຊ່ວຍໃຫ້ທ່ານເຂົ້າສູ່ຕະຫຼາດດ້ວຍເຄື່ອງມືສ້າງເວັບໄຊທີ່ຈະຊ່ວຍເລັ່ງຄວາມສຳເລັດໃນການປ່ຽນຕະຫຼາດອອບໄລນ໌ຂະໜາດໃຫຍ່ມາເປັນລູກຄ້າທີ່ຊໍາລະເງິນອອນໄລນ໌ໃຫ້ທ່ານ.";
$_ADMINLANG['marketConnect']['weebly']['learn']['aboutWeebly'] = "ກ່ຽວກັບ Weebly";
$_ADMINLANG['marketConnect']['weebly']['learn']['aboutWeeblyDescription'] = "ກໍ່ຕັ້ງຂຶ້ນໃນປີ 2007, Weebly ແມ່ນແພລັດຟອມລະດັບໂລກທີ່ມີສຳນັກງານຕັ້ງຢູ່ San Francisco ທີ່ຊ່ວຍໃຫ້ຜູ້ຄົນສ້າງເວັບໄຊ, ບລັອກ ຫຼື ຮ້ານຄ້າອອນໄລນ໌ທີ່ເປັນເອກະລັກໄດ້ຢ່າງງ່າຍດາຍ. ດ້ວຍຕົວແກ້ໄຂແບບລາກ ແລະ ວາງ ອອນໄລນ໌ທີ່ຊົງພະລັງ ແລະ ແອັບສຳລັບອຸປະກອນມືຖືທຸກລຸ້ນ, ໃນປະຈຸບັນມີຜູ້ຄົນ ແລະ ທຸລະກິດຂະໜາດນ້ອຍຫຼາຍກວ່າ 40 ລ້ານລາຍນຳໃຊ້ Weebly ເພື່ອສ້າງຕົວຕົນໃນໂລກອອນໄລນ໌.";
