$_ADMINLANG['marketConnect']['weebly']['faq']['a1'] = "ບັນຊີ Weebly Site Builder ຈະຖືກຈັດຕຽມທັນທີ ແລະ ເປັນອັດຕະໂນມັດ ເພື່ອໃຫ້ຜູ້ໃຊ້ສາມາດເຂົ້າສູ່ລະບົບ ແລະ ເລີ່ມສ້າງເວັບໄຊໃໝ່ໄດ້ທັນທີ.";
$_ADMINLANG['marketConnect']['weebly']['faq']['q2'] = "ຜູ້ໃຊ້ຈັດການເວັບໄຊຂອງພວກເຂົາແນວໃດ?";
$_ADMINLANG['marketConnect']['weebly']['faq']['a2'] = "ຜູ້ໃຊ້ສາມາດເຂົ້າເຖິງເຄື່ອງມືສ້າງເວັບໄຊ Weebly ໄດ້ໂດຍກົງຈາກ WHMCS Client Area ໂດຍໃຊ້ Single Sign-On ເພື່ອປະສົບການການເຂົ້າສູ່ລະບົບທີ່ໄຮ້ຮອຍຕໍ່.";
$_ADMINLANG['marketConnect']['weebly']['faq']['q3'] = "ການເຜີຍແຜ່ເວັບໄຊເຮັດວຽກແນວໃດ?";
$_ADMINLANG['marketConnect']['weebly']['faq']['a3'] = "ເມື່ອມີການສ້າງເວັບໄຊ Weebly, WHMCS ຈະຈັດຕຽມບັນຊີ FTP ທີ່ອຸທິດໃຫ້* ແລະ ສົ່ງລາຍລະອຽດເຫຼົ່ານັ້ນໃຫ້ກັບ Weebly. ເມື່ອຜູ້ໃຊ້ເຜີຍແຜ່ເວັບໄຊ, Weebly ຈະເຜີຍແຜ່ເວັບໄຊຜ່ານ FTP ໄປຫາໂຮດຕິ້ງຂອງທ່ານ.";
$_ADMINLANG['marketConnect']['weebly']['faq']['q4'] = "ຂ້ອຍຈະໂປຣໂມດ Weebly ໄດ້ແນວໃດ?";
$_ADMINLANG['marketConnect']['weebly']['faq']['a4'] = "ພວກເຮົາໄດ້ຈັດຕຽມໜ້າ Landing Page ທີ່ສ້າງໄວ້ລ່ວງໜ້າ (<a href=\":href\" target=\"_blank\">ເບິ່ງຕົວຢ່າງ</a>) ແລະ ຄວາມສາມາດໃນການສະແດງໂປຣໂມຊັນພາຍໃນ Client Area ແລະ ລະບົບສັ່ງຊື້.";
